### Step 1: Designing the Core Classes and Functions

To design a standard 2048 game, we need several core classes and functions. Here's a breakdown:

1. **GameBoard**: Manages the state of the game board, including the 4x4 grid and tile operations.
2. **Tile**: Represents a single tile on the board, with a value and position.
3. **GameController**: Handles user input and game logic, updating the board and managing the game state.
4. **GUI**: Provides a graphical user interface for the game.

### Step 2: Implementing the Files

#### 1. `tile.py`

```python
# tile.py

class Tile:
    def __init__(self, value=0, position=None):
        self.value = value
        self.position = position

    def __repr__(self):
        return f"Tile(value={self.value}, position={self.position})"
```

#### 2. `game_board.py`

```python
# game_board.py

from tile import Tile
import random

class GameBoard:
    def __init__(self):
        self.grid = [[None for _ in range(4)] for _ in range(4)]
        self.score = 0
        self.highest_tile = 0
        self.add_tile()
        self.add_tile()

    def add_tile(self):
        empty_cells = [(i, j) for i in range(4) for j in range(4) if self.grid[i][j] is None]
        if empty_cells:
            i, j = random.choice(empty_cells)
            self.grid[i][j] = Tile(value=2 if random.random() < 0.9 else 4, position=(i, j))

    def is_full(self):
        return all(self.grid[i][j] is not None for i in range(4) for j in range(4))

    def move(self, direction):
        moved = False
        if direction == 'up':
            for j in range(4):
                tiles = [self.grid[i][j] for i in range(4) if self.grid[i][j] is not None]
                new_tiles = self._merge_tiles(tiles)
                for i, tile in enumerate(new_tiles):
                    self.grid[i][j] = tile
                    self.grid[i][j].position = (i, j)
                for i in range(len(new_tiles), 4):
                    self.grid[i][j] = None
                moved = moved or len(new_tiles) != len(tiles)
        elif direction == 'down':
            for j in range(4):
                tiles = [self.grid[i][j] for i in range(3, -1, -1) if self.grid[i][j] is not None]
                new_tiles = self._merge_tiles(tiles)
                for i, tile in enumerate(new_tiles):
                    self.grid[3-i][j] = tile
                    self.grid[3-i][j].position = (3-i, j)
                for i in range(len(new_tiles), 4):
                    self.grid[3-i][j] = None
                moved = moved or len(new_tiles) != len(tiles)
        elif direction == 'left':
            for i in range(4):
                tiles = [self.grid[i][j] for j in range(4) if self.grid[i][j] is not None]
                new_tiles = self._merge_tiles(tiles)
                for j, tile in enumerate(new_tiles):
                    self.grid[i][j] = tile
                    self.grid[i][j].position = (i, j)
                for j in range(len(new_tiles), 4):
                    self.grid[i][j] = None
                moved = moved or len(new_tiles) != len(tiles)
        elif direction == 'right':
            for i in range(4):
                tiles = [self.grid[i][j] for j in range(3, -1, -1) if self.grid[i][j] is not None]
                new_tiles = self._merge_tiles(tiles)
                for j, tile in enumerate(new_tiles):
                    self.grid[i][3-j] = tile
                    self.grid[i][3-j].position = (i, 3-j)
                for j in range(len(new_tiles), 4):
                    self.grid[i][3-j] = None
                moved = moved or len(new_tiles) != len(tiles)
        if moved:
            self.add_tile()
            self.update_score()

    def _merge_tiles(self, tiles):
        new_tiles = []
        i = 0
        while i < len(tiles):
            if i + 1 < len(tiles) and tiles[i].value == tiles[i + 1].value:
                new_tiles.append(Tile(value=tiles[i].value * 2, position=tiles[i].position))
                self.score += tiles[i].value * 2
                self.highest_tile = max(self.highest_tile, tiles[i].value * 2)
                i += 2
            else:
                new_tiles.append(tiles[i])
                i += 1
        return new_tiles

    def update_score(self):
        pass

    def __str__(self):
        return '\n'.join([' '.join([str(self.grid[i][j].value if self.grid[i][j] else ' ') for j in range(4)]) for i in range(4)])
```

#### 3. `game_controller.py`

```python
# game_controller.py

from game_board import GameBoard

class GameController:
    def __init__(self):
        self.board = GameBoard()

    def handle_input(self, direction):
        self.board.move(direction)

    def get_board(self):
        return self.board

    def is_game_over(self):
        return self.board.is_full() and not any(self.board.move(direction) for direction in ['up', 'down', 'left', 'right'])
```

#### 4. `main.py`

```python
# main.py

import tkinter as tk
from game_controller import GameController

class GameApp:
    def __init__(self, root):
        self.root = root
        self.root.title("2048 Game")
        self.controller = GameController()
        self.canvas = tk.Canvas(root, width=400, height=400)
        self.canvas.pack()
        self.draw_board()
        self.root.bind("<Up>", lambda event: self.handle_input('up'))
        self.root.bind("<Down>", lambda event: self.handle_input('down'))
        self.root.bind("<Left>", lambda event: self.handle_input('left'))
        self.root.bind("<Right>", lambda event: self.handle_input('right'))

    def draw_board(self):
        self.canvas.delete("all")
        for i in range(4):
            for j in range(4):
                x1 = j * 100
                y1 = i * 100
                x2 = x1 + 100
                y2 = y1 + 100
                self.canvas.create_rectangle(x1, y1, x2, y2, fill="gray", outline="black")
                tile = self.controller.get_board().grid[i][j]
                if tile:
                    self.canvas.create_text(x1 + 50, y1 + 50, text=str(tile.value), font=("Arial", 20), fill="white")

    def handle_input(self, direction):
        self.controller.handle_input(direction)
        self.draw_board()
        if self.controller.is_game_over():
            self.canvas.create_text(200, 200, text="Game Over!", font=("Arial", 24), fill="red")

if __name__ == "__main__":
    root = tk.Tk()
    app = GameApp(root)
    root.mainloop()
```

### Explanation

1. **Tile Class**: Represents a single tile with a value and position.
2. **GameBoard Class**: Manages the 4x4 grid, tile operations, and game logic.
3. **GameController Class**: Handles user input and updates the game state.
4. **main.py**: The main application file that sets up the GUI and handles the game loop.

This implementation provides a fully functional 2048 game with a graphical user interface using Python and the Tkinter library.

